<?php

declare(strict_types=1);

$root = __DIR__;

$required = [
    'resources/views/layouts/pos.blade.php',
    'resources/views/surfaces/pos/register.blade.php',
    'resources/css/components/index.css',
];

foreach ($required as $relative) {
    $path = $root.DIRECTORY_SEPARATOR.str_replace('/', DIRECTORY_SEPARATOR, $relative);

    if (! is_file($path)) {
        fwrite(STDERR, "ERROR: Datei fehlt: {$relative}".PHP_EOL);
        exit(1);
    }
}

$stamp = date('Ymd_His');
$backupDir = $root.DIRECTORY_SEPARATOR.'.foundation'.DIRECTORY_SEPARATOR.'compat-backups'.DIRECTORY_SEPARATOR.'pos-staff-ui-'.$stamp;

if (! mkdir($backupDir, 0777, true) && ! is_dir($backupDir)) {
    fwrite(STDERR, 'ERROR: Backup-Verzeichnis konnte nicht erstellt werden.'.PHP_EOL);
    exit(1);
}

function backupFile(string $root, string $backupDir, string $relative): void
{
    $source = $root.DIRECTORY_SEPARATOR.str_replace('/', DIRECTORY_SEPARATOR, $relative);
    $target = $backupDir.DIRECTORY_SEPARATOR.str_replace('/', '__', $relative);

    if (! copy($source, $target)) {
        throw new RuntimeException("Backup fehlgeschlagen: {$relative}");
    }
}

function replaceOnce(string $content, string $search, string $replace, string $label): string
{
    if (! str_contains($content, $search)) {
        throw new RuntimeException("Erwarteter Block nicht gefunden: {$label}");
    }

    return preg_replace('/'.preg_quote($search, '/').'/', addcslashes($replace, '\\$'), $content, 1) ?? $content;
}

try {
    foreach ($required as $relative) {
        backupFile($root, $backupDir, $relative);
    }

    $layoutPath = $root.DIRECTORY_SEPARATOR.'resources'.DIRECTORY_SEPARATOR.'views'.DIRECTORY_SEPARATOR.'layouts'.DIRECTORY_SEPARATOR.'pos.blade.php';
