    $layout = str_replace(
        '<meta name="color-scheme" content="light">',
        '<meta name="color-scheme" content="dark">',
        $layout,
    );
    $layout = str_replace(
        '<meta name="theme-color" content="#0f172a">',
        '<meta name="theme-color" content="#101412">',
        $layout,
    );
