    file_put_contents($layoutPath, $layout);

    $registerPath = $root.DIRECTORY_SEPARATOR.'resources'.DIRECTORY_SEPARATOR.'views'.DIRECTORY_SEPARATOR.'surfaces'.DIRECTORY_SEPARATOR.'pos'.DIRECTORY_SEPARATOR.'register.blade.php';
