        ['<span class="hidden rounded-full px-2.5 py-1 text-xs font-bold sm:inline-flex {{ $session->status === CashSessionStatus::Open ? \'bg-emerald-100 text-emerald-800\' : \'bg-amber-100 text-amber-800\' }}">', '<span class="pos-session-badge hidden rounded-full px-2.5 py-1 text-xs font-bold sm:inline-flex {{ $session->status === CashSessionStatus::Open ? \'bg-emerald-100 text-emerald-800\' : \'bg-amber-100 text-amber-800\' }}">', 'Session badge'],
