        ['class="shrink-0 touch-manipulation rounded-xl px-4 py-3 text-sm font-bold {{ $selectedCategoryId === null ? \'bg-slate-950 text-white\' : \'bg-slate-100 text-slate-800\' }}"', 'class="pos-category-button shrink-0 touch-manipulation rounded-xl px-4 py-3 text-sm font-bold {{ $selectedCategoryId === null ? \'is-active\' : \'\' }}"', 'All category'],
        ['class="shrink-0 touch-manipulation rounded-xl px-4 py-3 text-sm font-bold {{ $selectedCategoryId === $category->id ? \'bg-slate-950 text-white\' : \'bg-slate-100 text-slate-800\' }}"', 'class="pos-category-button shrink-0 touch-manipulation rounded-xl px-4 py-3 text-sm font-bold {{ $selectedCategoryId === $category->id ? \'is-active\' : \'\' }}"', 'Category button'],
