        ['<div class="max-h-[46vh] divide-y divide-slate-100 overflow-y-auto">', '<div class="pos-cart__body max-h-[46vh] divide-y divide-slate-100 overflow-y-auto">', 'Cart body'],
        ['<div class="p-8 text-center text-slate-500">Noch keine Produkte ausgewählt.</div>', '<div class="pos-cart__empty p-8 text-center text-slate-500">Noch keine Produkte ausgewählt.</div>', 'Cart empty'],
        ['<div wire:key="cart-item-desktop-{{ $item->id }}" class="flex items-center gap-3 px-5 py-4">', '<div wire:key="cart-item-desktop-{{ $item->id }}" class="pos-cart__row flex items-center gap-3 px-5 py-4">', 'Cart row'],
        ['<p class="text-sm text-slate-500">{{ Money::format($item->unit_price_cents, $currency) }} je Stück</p>', '<p class="pos-cart__unit text-sm text-slate-500">{{ Money::format($item->unit_price_cents, $currency) }} je Stück</p>', 'Unit price'],
        ['<div class="flex items-center rounded-xl bg-slate-100 p-1">', '<div class="pos-quantity flex items-center rounded-xl bg-slate-100 p-1">', 'Quantity'],
        ['<div class="border-t border-slate-200 bg-slate-50 p-5">', '<div class="pos-cart__footer border-t border-slate-200 bg-slate-50 p-5">', 'Cart footer'],
        ['<span class="font-bold text-slate-600">Gesamt</span>', '<span class="pos-cart__total-label font-bold text-slate-600">Gesamt</span>', 'Total label'],
        ['<span class="text-4xl font-black tracking-tight">{{ Money::format($sale?->total_cents ?? 0, $currency) }}</span>', '<span class="pos-cart__total text-4xl font-black tracking-tight">{{ Money::format($sale?->total_cents ?? 0, $currency) }}</span>', 'Total'],
