    foreach ($replacements as [$search, $replace, $label]) {
        if (! str_contains($view, $search)) {
            throw new RuntimeException("POS-View weicht bei '{$label}' vom erwarteten Stand ab. Keine Datei wurde teilweise gespeichert.");
        }
        $view = str_replace($search, $replace, $view);
    }

    file_put_contents($registerPath, $view);

    $componentsPath = $root.DIRECTORY_SEPARATOR.'resources'.DIRECTORY_SEPARATOR.'css'.DIRECTORY_SEPARATOR.'components'.DIRECTORY_SEPARATOR.'index.css';
    $components = (string) file_get_contents($componentsPath);

    if (! str_contains($components, "@import './pos-terminal.css';")) {
        $components = "@import './pos-terminal.css';".PHP_EOL.PHP_EOL.$components;
        file_put_contents($componentsPath, $components);
    }

    $cssPath = $root.DIRECTORY_SEPARATOR.'resources'.DIRECTORY_SEPARATOR.'css'.DIRECTORY_SEPARATOR.'components'.DIRECTORY_SEPARATOR.'pos-terminal.css';
    file_put_contents($cssPath, base64_decode('', true));

    echo 'UPDATE  resources/views/layouts/pos.blade.php'.PHP_EOL;
    echo 'UPDATE  resources/views/surfaces/pos/register.blade.php'.PHP_EOL;
    echo 'UPDATE  resources/css/components/index.css'.PHP_EOL;
    echo 'WRITE   resources/css/components/pos-terminal.css'.PHP_EOL;
    echo 'BACKUP  '.str_replace($root.DIRECTORY_SEPARATOR, '', $backupDir).PHP_EOL;
    echo PHP_EOL;
    echo 'POS Mitarbeiter-UI installiert.'.PHP_EOL;
} catch (Throwable $exception) {
    fwrite(STDERR, 'ERROR: '.$exception->getMessage().PHP_EOL);
    fwrite(STDERR, "Die Originaldateien liegen unter: {$backupDir}".PHP_EOL);
    exit(1);
}
